function EventFinance(){const {base,query,entity,can}=useFinance(),action=useAction();const policies=useRows(base+'/event-policies'+query,!!entity),report=useRows(base+'/reports'+query+'&report=Event%20Finance',!!entity),me=useLoad<any>('/users/me');const [create,setCreate]=useState(false);return <EntityGate><div className="finance-page"><Heading title="One event. One finance engine." text="Paid registrations await verified funds or an explicitly authorized alternative settlement policy.">{can('finance.invoice')&&<button className="primary" onClick={()=>setCreate(true)}>Configure event pricing</button>}</Heading><Panel title="Pricing and approval"><Table rows={policies.rows} columns={[{key:'memberPrice',label:'Member price',render:(r:any)=>money(r.memberPrice,r.currency)},{key:'guestPrice',label:'Guest / companion price',render:(r:any)=>money(r.guestPrice,r.currency)},{key:'active',label:'Pricing state',render:(r:any)=><Badge>{r.active?'Approved':'Pending approval'}</Badge>},{key:'allowManualSettlement',label:'Alternative settlement',render:(r:any)=>r.allowManualSettlement?'Approved manual collection permitted':'Verified gateway required'},{key:'review',label:'Review',render:(r:any)=>!r.approvedBy&&r.authorId!==me.data?.id&&can('finance.approve')?<button onClick={()=>action.run(()=>api(base+'/event-policies/'+r.id+'/decision','POST',{decision:'Approve',note:'Reviewed event fee policy'}),'Event pricing approved')}>Approve pricing</button>:'—'}]}/></Panel><Panel title="Event accrual and collections"><Table rows={report.rows} columns={reportColumns(report.rows,entity?.currency)}/></Panel>{create&&<EventPriceEditor onClose={()=>setCreate(false)}/>}</div></EntityGate>}

